abstract class Shape { abstract double area(); abstract double perimeter(); }
class Circle extends Shape { double r; Circle(double r) { this.r = r; } double area() { return Math.PI*r*r; } double perimeter() { return 2*Math.PI*r; } }
class Rectangle extends Shape { double w,h; Rectangle(double w,double h) { this.w=w; this.h=h; } double area() { return w*h; } double perimeter() { return 2*(w+h); } }

static void printStats(Shape[] shapes) {
    double total = 0; Shape largest = shapes[0], smallest = shapes[0];
    for (Shape s : shapes) {
        System.out.println(s.area() + " " + s.perimeter());
        total += s.area();
        if (s.area() > largest.area()) largest = s;
        if (s.area() < smallest.area()) smallest = s;
    }
    System.out.println("Total: " + total + " Largest: " + largest.area() + " Smallest: " + smallest.area());
}

public static void main(String[] args) {
    printStats(new Shape[]{ new Circle(3), new Rectangle(4,5) });
}

interface ComparableStudent { int compareTo(ComparableStudent other); }
class Student implements ComparableStudent {
    String name; double gpa;
    Student(String n, double g) { name = n; gpa = g; }
    public int compareTo(ComparableStudent other) { return Double.compare(gpa, ((Student) other).gpa); }
}

static void bubbleSort(ComparableStudent[] arr) {
    for (int i=0;i<arr.length;i++) for (int j=0;j<arr.length-1-i;j++)
        if (arr[j].compareTo(arr[j+1]) > 0) { ComparableStudent t=arr[j]; arr[j]=arr[j+1]; arr[j+1]=t; }
}

public static void main(String[] args) {
    Student[] students = { new Student("A", 3.5), new Student("B", 2.8), new Student("C", 4.0) };
    bubbleSort(students);
    for (ComparableStudent s : students) System.out.println(((Student) s).name);
}

interface Command { void execute(); void undo(); }
class AddCommand implements Command { public void execute() { System.out.println("Add wykonane"); } public void undo() { System.out.println("Add cofniete"); } }
class DeleteCommand implements Command { public void execute() { System.out.println("Delete wykonane"); } public void undo() { System.out.println("Delete cofniete"); } }

public static void main(String[] args) {
    Command[] history = { new AddCommand(), new DeleteCommand() };
    for (Command c : history) c.execute();
    for (int i = history.length - 1; i >= 0; i--) history[i].undo();
}

interface TaxStrategy { double calculate(double income); }
class FlatTax implements TaxStrategy { public double calculate(double income) { return income * 0.19; } }
class ProgressiveTax implements TaxStrategy {
    public double calculate(double income) {
        if (income <= 120000) return income * 0.12;
        return 120000 * 0.12 + (income - 120000) * 0.32;
    }
}
class Taxpayer { TaxStrategy strategy; Taxpayer(TaxStrategy s) { strategy = s; } double netIncome(double gross) { return gross - strategy.calculate(gross); } }

public static void main(String[] args) {
    System.out.println(new Taxpayer(new FlatTax()).netIncome(50000));
    System.out.println(new Taxpayer(new ProgressiveTax()).netIncome(150000));
}

interface Visitor { void visit(Circle c); void visit(Rectangle r); }
class Circle { double radius; Circle(double r) { radius = r; } void accept(Visitor v) { v.visit(this); } }
class Rectangle { double w, h; Rectangle(double w, double h) { this.w = w; this.h = h; } void accept(Visitor v) { v.visit(this); } }
class AreaVisitor implements Visitor {
    public void visit(Circle c) { System.out.println("Pole kola: " + Math.PI * c.radius * c.radius); }
    public void visit(Rectangle r) { System.out.println("Pole prostokata: " + r.w * r.h); }
}

public static void main(String[] args) {
    Circle c = new Circle(3); Rectangle r = new Rectangle(4, 5);
    Visitor v = new AreaVisitor();
    c.accept(v); r.accept(v);
}

