abstract class Handler {
    Handler next;
    Handler(Handler next) { this.next = next; }
    abstract void handle(int request);
}
class LowHandler extends Handler {
    LowHandler(Handler next) { super(next); }
    void handle(int request) { if (request <= 10) System.out.println("Low obsluzyl: " + request); else next.handle(request); }
}
class MidHandler extends Handler {
    MidHandler(Handler next) { super(next); }
    void handle(int request) { if (request <= 50) System.out.println("Mid obsluzyl: " + request); else next.handle(request); }
}
class HighHandler extends Handler {
    HighHandler(Handler next) { super(next); }
    void handle(int request) { System.out.println("High obsluzyl: " + request); }
}

public static void main(String[] args) {
    Handler chain = new LowHandler(new MidHandler(new HighHandler(null)));
    chain.handle(5); chain.handle(25); chain.handle(75);
}

interface ImageLoader { void load(String url); }
class RealImageLoader implements ImageLoader { public void load(String url) { System.out.println("Loading: " + url); } }
class CachingProxy implements ImageLoader {
    java.util.Set<String> cache = new java.util.HashSet<>();
    RealImageLoader real = new RealImageLoader();
    public void load(String url) {
        if (cache.contains(url)) System.out.println("[CACHE HIT] " + url);
        else { real.load(url); cache.add(url); }
    }
}

public static void main(String[] args) {
    ImageLoader loader = new CachingProxy();
    loader.load("a.png"); loader.load("a.png"); loader.load("b.png");
}

