interface Calc { int compute(int n); }
class DirectCalc implements Calc { public int compute(int n) { return n * n; } }

public static void main(String[] args) {
    DirectCalc directCalc = new DirectCalc();
    Calc polymorphicCalc = new DirectCalc();
    long start1 = System.nanoTime();
    for (int i = 0; i < 1_000_000; i++) directCalc.compute(i);
    long time1 = System.nanoTime() - start1;
    long start2 = System.nanoTime();
    for (int i = 0; i < 1_000_000; i++) polymorphicCalc.compute(i);
    long time2 = System.nanoTime() - start2;
    System.out.println("Bezposrednio: " + time1 + "ns, polimorficznie: " + time2 + "ns");
    // Po "rozgrzaniu" JIT (kompilacja just-in-time) czasy zwykle sie wyrownuja - JIT potrafi
    // 'zdewirtualizowac' wywolanie, gdy w praktyce zawsze widzi TEN SAM konkretny typ.
}
